function sql(value) { if (value === undefined || value === null || String(value).trim() === '') return 'NULL'; return "'" + String(value).replace(/'/g, "''") + "'"; }
const body = $json.body || $json;
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const baseUrl = String(body.baseUrl || body.base_url || 'http://minio:9000').replace(/\/$/, '');
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(publicationJobId)) return [{ json: { query: "SELECT false AS ok, 'publicationJobId is required' AS error, NULL AS \"publicationJobId\", '{}'::jsonb AS \"promptPack\", '[]'::jsonb AS references, " + sql(baseUrl) + " AS \"baseUrl\";" } }];
const query = `
WITH job AS (
  SELECT * FROM publication_jobs WHERE publication_job_id = ${sql(publicationJobId)}::uuid LIMIT 1
), refs AS (
  SELECT jsonb_array_elements(COALESCE((SELECT prompt_pack FROM job)->'identityReferences', '[]'::jsonb)) AS ref
)
SELECT
  EXISTS(SELECT 1 FROM job) AS ok,
  CASE WHEN NOT EXISTS(SELECT 1 FROM job) THEN 'Publication job not found' ELSE NULL END AS error,
  (SELECT publication_job_id FROM job) AS "publicationJobId",
  (SELECT prompt_pack FROM job) AS "promptPack",
  COALESCE((SELECT jsonb_agg(ref) FROM refs), '[]'::jsonb) AS references,
  ${sql(baseUrl)} AS "baseUrl";
`;
return [{ json: { ok: true, query } }];

const row = $input.first()?.json || {};
function parse(value, fallback) { if (value == null) return fallback; if (typeof value === 'string') { try { return JSON.parse(value); } catch { return fallback; } } return value; }
if (row.ok === false || row.ok === 'f') return [{ json: { ok: false, error: row.error || 'Reference context not found' } }];
const publicationJobId = row.publicationJobId;
const baseUrl = String(row.baseUrl || 'http://minio:9000').replace(/\/$/, '');
const references = parse(row.references, []);
const prepared = [];
const failed = [];
for (const ref of references) {
  if (!ref || typeof ref !== 'object') continue;
  if (String(ref.comfyInputName || '').trim()) {
    prepared.push({ ...ref, reused: true });
    continue;
  }
  const assetId = ref.assetId || ref.asset_id;
  const bucket = ref.minioBucket || ref.bucket;
  const objectPath = ref.minioObjectPath || ref.objectPath;
  if (!assetId || !bucket || !objectPath) {
    failed.push({ ref, error: 'Reference is missing assetId, bucket, or objectPath' });
    continue;
  }
  try {
    const imageUrl = baseUrl + '/' + encodeURIComponent(bucket) + '/' + String(objectPath).split('/').map(encodeURIComponent).join('/');
    const image = await this.helpers.httpRequest({ method: 'GET', url: imageUrl, encoding: 'arraybuffer', timeout: 120000, returnFullResponse: true });
    const buffer = Buffer.from(image.body);
    const mimeType = image.headers?.['content-type'] || image.headers?.['Content-Type'] || 'image/png';
    const upload = await this.helpers.httpRequest({ method: 'POST', url: 'http://ai-gateway:8095/comfy/prepare-reference', headers: { 'Content-Type': 'application/json', 'X-Request-Id': 'prepare-reference-' + assetId }, body: { assetId, bucket, objectPath, filename: objectPath.split('/').pop(), mimeType, fileBase64: buffer.toString('base64') }, json: true, timeout: 120000 });
    if (!upload?.ok || !upload.comfyInputName) {
      failed.push({ assetId, bucket, objectPath, error: upload?.error || 'Comfy reference upload failed', upload });
      continue;
    }
    prepared.push({ ...ref, assetId, minioBucket: bucket, minioObjectPath: objectPath, comfyInputName: upload.comfyInputName, comfyLoadable: true, preparedAt: new Date().toISOString(), prepareProvider: 'comfy-cloud', prepareResponse: upload.response || null });
  } catch (error) {
    failed.push({ assetId, bucket, objectPath, error: error?.message || 'Reference preparation failed' });
  }
}
return [{ json: { ok: failed.length === 0, publicationJobId, prepared, failed, preparedCount: prepared.length, failedCount: failed.length } }];

function sql(value) { if (value === undefined || value === null || String(value).trim() === '') return 'NULL'; return "'" + String(value).replace(/'/g, "''") + "'"; }
function sqlJson(value) { return sql(JSON.stringify(value ?? {})) + '::jsonb'; }
const row = $input.first()?.json || {};
if (!row.publicationJobId) return [{ json: { query: "SELECT false AS ok, 'publicationJobId is required' AS error;" } }];
const prepared = Array.isArray(row.prepared) ? row.prepared : [];
const failed = Array.isArray(row.failed) ? row.failed : [];
const values = prepared.map((ref) => '(' + sql(ref.assetId) + ', ' + sql(ref.comfyInputName) + ', ' + sqlJson(ref) + ')').join('\n');
const updateRefs = values ? `, ref_values(asset_id, comfy_input_name, ref_payload) AS (VALUES ${values}), registry_update AS (UPDATE canonical_asset_registry car SET metadata = COALESCE(car.metadata, '{}'::jsonb) || jsonb_build_object('comfyInputName', rv.comfy_input_name, 'comfyPreparedAt', now(), 'comfyReference', rv.ref_payload), updated_at = now() FROM ref_values rv WHERE car.asset_id::text = rv.asset_id RETURNING car.asset_id, car.metadata)` : ', registry_update AS (SELECT NULL::text AS asset_id, NULL::jsonb AS metadata WHERE false)';
const query = `
WITH input AS (SELECT ${sql(row.publicationJobId)}::uuid AS publication_job_id, ${sqlJson(prepared)} AS prepared, ${sqlJson(failed)} AS failed)
${updateRefs}
, job_update AS (
  UPDATE publication_jobs pj
  SET prompt_pack = jsonb_set(COALESCE(prompt_pack, '{}'::jsonb), '{identityReferences}', (SELECT prepared FROM input), true),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('preparedIdentityReferences', (SELECT prepared FROM input), 'prepareReferenceFailures', (SELECT failed FROM input), 'referencesPreparedAt', now()),
      updated_at = now()
  WHERE publication_job_id = (SELECT publication_job_id FROM input)
  RETURNING *
)
SELECT
  ${row.failedCount ? 'false' : 'true'} AS ok,
  CASE WHEN ${row.failedCount || 0} > 0 THEN 'Some references could not be prepared' ELSE NULL END AS error,
  ${Number(row.preparedCount || 0)}::int AS "preparedCount",
  ${Number(row.failedCount || 0)}::int AS "failedCount",
  ${sqlJson(prepared)} AS prepared,
  ${sqlJson(failed)} AS failed,
  (SELECT jsonb_build_object('publicationJobId', publication_job_id, 'avatar', avatar, 'scene', scene, 'format', format, 'objective', objective, 'businessProfile', business_profile, 'assetType', asset_type, 'status', status, 'brief', brief, 'promptPack', prompt_pack, 'publishingPack', publishing_pack, 'metadata', metadata, 'createdAt', created_at, 'updatedAt', updated_at) FROM job_update) AS job;
`;
return [{ json: { query } }];

function parse(value, fallback) { if (value == null) return fallback; if (typeof value === 'string') { try { return JSON.parse(value); } catch { return fallback; } } return value; }
const row = $input.first()?.json || {};
const ok = row.ok === true || row.ok === 't';
return [{ json: { ok, error: row.error || null, preparedCount: Number(row.preparedCount || 0), failedCount: Number(row.failedCount || 0), prepared: parse(row.prepared, []), failed: parse(row.failed, []), job: parse(row.job, null) } }];
